def polynomialAutomorphism (N : ℕ) (f g : P → HomogeneousPowerBasis.Poly)
    (p : P) (t : ℂ) : Pair ≃ₜ Pair :=
  automorphism N (fun p => extract N (f p) (g p)) p t

